const asBool = (v) => {
  if (v === true || v === 1) return true;
  if (v === false || v === 0 || v == null) return false;
  const s = String(v).trim().toLowerCase();
  return s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on';
};

const toNum = (v, def = 0) => {
  if (v == null) return def;
  if (typeof v === 'number') return Number.isFinite(v) ? v : def;
  const s = String(v).trim();
  if (!s) return def;
  const n = Number(s);
  return Number.isFinite(n) ? n : def;
};

const getNestedLinePayload = (obj) => isPlainObject(obj?.row_json)
  ? obj.row_json
  : (isPlainObject(obj?.rowJson) ? obj.rowJson : {});

const firstPresentPreviewValue = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && !trimStr(value)) continue;
    return value;
  }
  return undefined;
};

const firstFinitePreviewNumber = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && !trimStr(value)) continue;
    const n = Number(value);
    if (Number.isFinite(n)) return n;
  }
  return null;
};

const getLinePresentationSection = (obj) => {
  const section = (typeof getBankingPayAdoptedPreviewRowSectionV1 === 'function')
    ? getBankingPayAdoptedPreviewRowSectionV1(obj)
    : '';
  if (section === 'canonical_preview_lines') return 'READY_TO_PAY';
  if (section === 'cases_resolutions') return 'CASES_RESOLUTIONS';
  if (section === 'blocked_for_pay') return 'BLOCKED_FOR_PAY';
  if (section === 'hidden') return 'HIDDEN';
  const nested = getNestedLinePayload(obj);
  return upperTrim(obj?.presentation_section || obj?.presentationSection || nested?.presentation_section || nested?.presentationSection || '');
};

const isPreviewChildRow = (obj) => {
  const nested = getNestedLinePayload(obj);
  return upperTrim(obj?.presentation_role || obj?.presentationRole || nested?.presentation_role || nested?.presentationRole || '') === 'CHILD';
};

const getLineSectionAmount = (obj) => {
  const nested = getNestedLinePayload(obj);
  if (isPreviewChildRow(obj)) return getLineRowLevelAmount(obj);
  return firstPresentPreviewValue(
    obj?.section_amount_display,
    obj?.sectionAmountDisplay,
    nested?.section_amount_display,
    nested?.sectionAmountDisplay,
    obj?.section_amount_ex_vat,
    obj?.sectionAmountExVat,
    nested?.section_amount_ex_vat,
    nested?.sectionAmountExVat,
    obj?.section_non_segment_amount_ex_vat,
    obj?.sectionNonSegmentAmountExVat,
    nested?.section_non_segment_amount_ex_vat,
    nested?.sectionNonSegmentAmountExVat,
    getLineRowLevelAmount(obj)
  );
};

const getLineSourceBasisJson = (obj) => {
  const nested = getNestedLinePayload(obj);
  if (isPlainObject(obj?.source_basis_json)) return obj.source_basis_json;
  if (isPlainObject(obj?.sourceBasisJson)) return obj.sourceBasisJson;
  if (isPlainObject(nested?.source_basis_json)) return nested.source_basis_json;
  if (isPlainObject(nested?.sourceBasisJson)) return nested.sourceBasisJson;
  return {};
};

const getLineCaseComponents = (obj) => {
  const nested = getNestedLinePayload(obj);
  return [
    ...asArray(obj?.case_components),
    ...asArray(obj?.caseComponents),
    ...asArray(nested?.case_components),
    ...asArray(nested?.caseComponents)
  ].filter((component) => isPlainObject(component));
};

const getLineKeyType = (obj) => {
  const nested = getNestedLinePayload(obj);
  const economicKey = isPlainObject(obj?.economic_key) ? obj.economic_key : (isPlainObject(obj?.economicKey) ? obj.economicKey : {});
  return upperTrim(
    obj?.key_type ||
    obj?.keyType ||
    economicKey?.key_type ||
    economicKey?.keyType ||
    nested?.key_type ||
    nested?.keyType ||
    ''
  );
};

const getLineKeyValue = (obj) => {
  const nested = getNestedLinePayload(obj);
  const economicKey = isPlainObject(obj?.economic_key) ? obj.economic_key : (isPlainObject(obj?.economicKey) ? obj.economicKey : {});
  return trimStr(
    obj?.key_value ||
    obj?.keyValue ||
    economicKey?.key_value ||
    economicKey?.keyValue ||
    nested?.key_value ||
    nested?.keyValue ||
    ''
  );
};

const getLineCandidateId = (obj) => {
  const nested = getNestedLinePayload(obj);
  return trimStr(obj?.candidate_id || obj?.candidateId || nested?.candidate_id || nested?.candidateId || '');
};

const getLineTimesheetId = (obj) => {
  const nested = getNestedLinePayload(obj);
  const economicKey = isPlainObject(obj?.economic_key) ? obj.economic_key : (isPlainObject(obj?.economicKey) ? obj.economicKey : {});
  return trimStr(
    obj?.timesheet_id ||
    obj?.timesheetId ||
    obj?.linked_timesheet_id ||
    obj?.linkedTimesheetId ||
    economicKey?.timesheet_id ||
    economicKey?.timesheetId ||
    nested?.timesheet_id ||
    nested?.timesheetId ||
    nested?.linked_timesheet_id ||
    nested?.linkedTimesheetId ||
    ''
  );
};

const getRelatedTimesheetIds = (obj) => {
  const ids = [];
  const seenIds = new Set();
  const seenObjects = new WeakSet();
  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  const addId = (value) => {
    const id = trimStr(value);
    if (!uuidRe.test(id) || seenIds.has(id)) return;
    seenIds.add(id);
    ids.push(id);
  };
  const visit = (value, depth = 0) => {
    if (!value || depth > 8) return;
    if (Array.isArray(value)) {
      value.forEach((item) => visit(item, depth + 1));
      return;
    }
    if (!isPlainObject(value) || seenObjects.has(value)) return;
    seenObjects.add(value);

    [
      value.timesheet_id,
      value.timesheetId,
      value.linked_timesheet_id,
      value.linkedTimesheetId,
      value.original_timesheet_id,
      value.originalTimesheetId,
      value.current_timesheet_id,
      value.currentTimesheetId
    ].forEach(addId);
    [
      value.timesheet_ids,
      value.timesheetIds,
      value.linked_timesheet_ids,
      value.linkedTimesheetIds,
      value.selected_timesheet_ids,
      value.selectedTimesheetIds,
      value.affected_timesheet_ids,
      value.affectedTimesheetIds
    ].forEach((values) => asArray(values).forEach(addId));

    [
      value.economic_key,
      value.economicKey,
      value.row_json,
      value.rowJson,
      value.source_basis_json,
      value.sourceBasisJson,
      value.case_resolution_summary,
      value.caseResolutionSummary,
      value.__case_entry,
      value.raw_case,
      value.rawCase,
      value.payload_json,
      value.payloadJson,
      value.frozen_resolution_payload_json,
      value.frozenResolutionPayloadJson
    ].forEach((nested) => visit(nested, depth + 1));
    [
      value.components,
      value.case_components,
      value.caseComponents,
      value.resolution_components,
      value.resolutionComponents,
      value.resolution_rows,
      value.resolutionRows,
      value.bucket_resolutions,
      value.bucketResolutions,
      value.overpayment_components,
      value.overpaymentComponents,
      value.display_lines,
      value.displayLines
    ].forEach((rows) => visit(rows, depth + 1));
  };
  visit(obj);
  return ids;
};

const isSyntheticTimesheetResidualLine = (obj, siblingRows = []) => {
  if (!isPlainObject(obj)) return false;
  const nested = getNestedLinePayload(obj);
  const sourceBasis = getLineSourceBasisJson(obj);
  const keyType = getLineKeyType(obj);
  const keyValue = upperTrim(getLineKeyValue(obj));
  const identityText = [
    obj?.row_key,
    obj?.rowKey,
    obj?.line_key,
    obj?.lineKey,
    obj?.source_ref,
    obj?.sourceRef,
    obj?.preview_row_id,
    obj?.previewRowId,
    nested?.row_key,
    nested?.rowKey,
    nested?.line_key,
    nested?.lineKey,
    nested?.source_ref,
    nested?.sourceRef
  ].map((value) => trimStr(value).toLowerCase()).filter(Boolean).join('|');
  const sourceKeyType = upperTrim(sourceBasis?.component_key_type || sourceBasis?.componentKeyType || '');
  const sourceKeyValue = upperTrim(sourceBasis?.component_key_value || sourceBasis?.componentKeyValue || '');
  const isTimesheetTotal = (
    (keyType === 'TS_TOTAL' && keyValue === 'TOTAL') ||
    (sourceKeyType === 'TS_TOTAL' && sourceKeyValue === 'TOTAL')
  );
  if (!identityText.includes(':non_segment:total') || !isTimesheetTotal) return false;

  const explicitResolvedReplacementMarker = asBool(
    obj?.resolved_segment_rows_replace_source_total ??
    obj?.resolvedSegmentRowsReplaceSourceTotal ??
    nested?.resolved_segment_rows_replace_source_total ??
    nested?.resolvedSegmentRowsReplaceSourceTotal ??
    sourceBasis?.resolved_segment_rows_replace_source_total ??
    sourceBasis?.resolvedSegmentRowsReplaceSourceTotal
  );
  if (explicitResolvedReplacementMarker) return true;

  const timesheetId = getLineTimesheetId(obj);
  return asArray(siblingRows).some((candidate) => {
    if (!isPlainObject(candidate) || candidate === obj) return false;
    if (getLineKeyType(candidate) !== 'TS_DAY') return false;
    const candidateTimesheetId = getLineTimesheetId(candidate);
    return (!timesheetId || !candidateTimesheetId || candidateTimesheetId === timesheetId);
  });
};

const isOverpaymentRecoveryLine = (obj) => {
  const nested = getNestedLinePayload(obj);
  return upperTrim(obj?.line_type || obj?.lineType || nested?.line_type || nested?.lineType || '') === 'OVERPAYMENT_RECOVERY';
};

const isManualDebtRecoveryLine = (obj) => {
  const nested = getNestedLinePayload(obj);
  return upperTrim(obj?.line_type || obj?.lineType || nested?.line_type || nested?.lineType || '') === 'MANUAL_DEBT_RECOVERY';
};

const getOverpaymentRecoveryPresentationGroupKey = (obj) => {
  if (!isOverpaymentRecoveryLine(obj)) return '';
  const line = isPlainObject(obj) ? obj : {};
  const nested = getNestedLinePayload(line);
  const financeCaseId = trimStr(
    line?.finance_case_id ||
    line?.financeCaseId ||
    nested?.finance_case_id ||
    nested?.financeCaseId ||
    ''
  );
  if (financeCaseId) return `finance:${financeCaseId}:overpayment_recovery`;
  const parentLineId = trimStr(
    line?.presentation_parent_line_id ||
    line?.presentationParentLineId ||
    nested?.presentation_parent_line_id ||
    nested?.presentationParentLineId ||
    ''
  );
  return parentLineId;
};

const getOverpaymentRecoveryPresentation = (obj) => {
  if (!isOverpaymentRecoveryLine(obj)) return null;
  const line = isPlainObject(obj) ? obj : {};
  const nested = getNestedLinePayload(line);
  const caseSummary = isPlainObject(line?.case_resolution_summary)
    ? line.case_resolution_summary
    : (isPlainObject(nested?.case_resolution_summary) ? nested.case_resolution_summary : {});
  const recoveryHeadroom = isPlainObject(line?.selection_recovery_headroom_v1)
    ? line.selection_recovery_headroom_v1
    : (isPlainObject(nested?.selection_recovery_headroom_v1)
        ? nested.selection_recovery_headroom_v1
        : {});
  const toMagnitude = (...values) => {
    const value = firstFinitePreviewNumber(...values);
    return value === null ? null : Math.abs(Math.round(value * 100) / 100);
  };
  const rawComponents = getLineCaseComponents(line).map((component, index) => {
    const original = toMagnitude(
      component?.resolved_target_amount_ex_vat,
      component?.resolvedTargetAmountExVat,
      component?.target_pay_ex_vat,
      component?.targetPayExVat,
      component?.source_amount,
      component?.sourceAmount,
      component?.source_pay_ex_vat,
      component?.sourcePayExVat,
      component?.remaining_source_amount,
      component?.remainingSourceAmount
    );
    const outstanding = toMagnitude(
      component?.target_outstanding_ex_vat,
      component?.targetOutstandingExVat,
      component?.remaining_source_amount,
      component?.remainingSourceAmount,
      original
    );
    const recoverableThisRun = toMagnitude(
      component?.preview_due_amount_ex_vat,
      component?.previewDueAmountExVat,
      component?.allocated_source_due_amount_ex_vat,
      component?.allocatedSourceDueAmountExVat,
      component?.target_pay_ex_vat,
      component?.targetPayExVat,
      0
    ) ?? 0;
    return {
      index,
      label: getOverpaymentComponentFriendlyLabel(component),
      original,
      outstanding,
      recoverable_this_run: recoverableThisRun
    };
  }).filter((component) => component.original !== null || component.outstanding !== null);

  const rowRecoverable = toMagnitude(
    line?.recoverable_this_pay_run_ex_vat,
    line?.recoverableThisPayRunExVat,
    nested?.recoverable_this_pay_run_ex_vat,
    nested?.recoverableThisPayRunExVat,
    recoveryHeadroom?.recoverable_amount_ex_vat,
    recoveryHeadroom?.recoverableAmountExVat,
    getLineRowLevelAmount(line),
    getLineSectionAmount(line),
    0
  ) ?? 0;
  const rawComponentRecoverableTotal = Math.round(rawComponents.reduce(
    (total, component) => total + Math.max(0, component.recoverable_this_run ?? 0),
    0
  ) * 100) / 100;
  const useCertifiedRowRecoveryAllocation = rowRecoverable > 0
    && Math.round(rawComponentRecoverableTotal * 100) !== Math.round(rowRecoverable * 100);
  let remainingRowRecovery = rowRecoverable;
  const components = rawComponents.map((component) => {
    const rawRecoverable = useCertifiedRowRecoveryAllocation
      ? Math.max(0, component.outstanding ?? component.original ?? 0)
      : Math.max(0, component.recoverable_this_run ?? 0);
    const allocatedRecoverable = Math.round(Math.min(rawRecoverable, remainingRowRecovery) * 100) / 100;
    remainingRowRecovery = Math.round(Math.max(remainingRowRecovery - allocatedRecoverable, 0) * 100) / 100;
    return {
      ...component,
      recoverable_this_run: allocatedRecoverable
    };
  });
  const componentOriginalTotal = Math.round(components.reduce((total, component) => total + (component.original ?? 0), 0) * 100) / 100;
  const componentOutstandingTotal = Math.round(components.reduce((total, component) => total + (component.outstanding ?? 0), 0) * 100) / 100;
  const componentRecoverableTotal = Math.round(components.reduce((total, component) => total + (component.recoverable_this_run ?? 0), 0) * 100) / 100;
  const fallbackOutstanding = toMagnitude(
    line?.nominal_due_amount_ex_vat,
    line?.nominalDueAmountExVat,
    nested?.nominal_due_amount_ex_vat,
    nested?.nominalDueAmountExVat,
    line?.case_outstanding_amount,
    line?.caseOutstandingAmount,
    nested?.case_outstanding_amount,
    nested?.caseOutstandingAmount,
    line?.outstanding_amount,
    line?.outstandingAmount,
    nested?.outstanding_amount,
    nested?.outstandingAmount,
    caseSummary?.nominal_due_amount_ex_vat,
    caseSummary?.nominalDueAmountExVat,
    rowRecoverable
  ) ?? 0;
  const outstandingTotal = components.length ? componentOutstandingTotal : fallbackOutstanding;
  const originalTotal = components.length ? componentOriginalTotal : Math.max(outstandingTotal, rowRecoverable);
  const recoverableThisRun = components.length ? Math.min(componentRecoverableTotal, rowRecoverable) : rowRecoverable;
  const blockedReasons = [
    ...asArray(line?.blocked_reason_codes),
    ...asArray(line?.blockedReasonCodes),
    ...asArray(nested?.blocked_reason_codes),
    ...asArray(nested?.blockedReasonCodes),
    ...asArray(caseSummary?.blocked_reason_codes),
    ...asArray(caseSummary?.blockedReasonCodes),
    line?.presentation_reason,
    line?.presentationReason,
    nested?.presentation_reason,
    nested?.presentationReason
  ].map((value) => upperTrim(value)).filter(Boolean);

  return {
    components,
    original_total: originalTotal,
    outstanding_total: outstandingTotal,
    recoverable_this_run: recoverableThisRun,
    no_available_funds: outstandingTotal > 0 && recoverableThisRun === 0 && blockedReasons.includes('NO_PAY_HEADROOM')
  };
};

const getManualDebtRecoveryPresentation = (obj) => {
  if (!isManualDebtRecoveryLine(obj)) return null;
  const line = isPlainObject(obj) ? obj : {};
  const nested = getNestedLinePayload(line);
  const caseSummary = isPlainObject(line?.case_resolution_summary)
    ? line.case_resolution_summary
    : (isPlainObject(nested?.case_resolution_summary) ? nested.case_resolution_summary : {});
  const components = getLineCaseComponents(line);
  const componentDueValues = components.flatMap((component) => {
    const sourceBasis = isPlainObject(component?.source_basis_json)
      ? component.source_basis_json
      : (isPlainObject(component?.sourceBasisJson) ? component.sourceBasisJson : {});
    return [
      component?.nominal_due_amount_ex_vat,
      component?.nominalDueAmountExVat,
      sourceBasis?.nominal_due_amount_ex_vat,
      sourceBasis?.nominalDueAmountExVat,
      sourceBasis?.weekly_due,
      sourceBasis?.weeklyDue
    ];
  });
  const toMagnitude = (...values) => {
    const value = firstFinitePreviewNumber(...values);
    return value === null ? null : Math.abs(Math.round(value * 100) / 100);
  };
  const scheduledDue = toMagnitude(
    line?.nominal_due_amount_ex_vat,
    line?.nominalDueAmountExVat,
    nested?.nominal_due_amount_ex_vat,
    nested?.nominalDueAmountExVat,
    caseSummary?.nominal_due_amount_ex_vat,
    caseSummary?.nominalDueAmountExVat,
    ...componentDueValues
  ) ?? 0;
  const recoverableThisRun = toMagnitude(
    line?.recoverable_this_pay_run_ex_vat,
    line?.recoverableThisPayRunExVat,
    nested?.recoverable_this_pay_run_ex_vat,
    nested?.recoverableThisPayRunExVat,
    getLineRowLevelAmount(line),
    getLineSectionAmount(line),
    0
  ) ?? 0;
  const blockedReasons = [
    ...asArray(line?.blocked_reason_codes),
    ...asArray(line?.blockedReasonCodes),
    ...asArray(nested?.blocked_reason_codes),
    ...asArray(nested?.blockedReasonCodes),
    ...asArray(caseSummary?.blocked_reason_codes),
    ...asArray(caseSummary?.blockedReasonCodes),
    line?.presentation_reason,
    line?.presentationReason,
    nested?.presentation_reason,
    nested?.presentationReason
  ].map((value) => upperTrim(value)).filter(Boolean);

  return {
    scheduled_due: scheduledDue,
    recoverable_this_run: recoverableThisRun,
    no_available_funds: scheduledDue > 0 && recoverableThisRun === 0 && blockedReasons.includes('NO_PAY_HEADROOM')
  };
};

const getPreviewLineDisplayAmount = (line) => {
  const manualDebtRecovery = getManualDebtRecoveryPresentation(line);
  if (manualDebtRecovery?.no_available_funds) return -Math.abs(manualDebtRecovery.scheduled_due);
  const recovery = getOverpaymentRecoveryPresentation(line);
  if (recovery) return recovery.recoverable_this_run > 0 ? -Math.abs(recovery.recoverable_this_run) : 0;
  return getLineSectionAmount(line);
};

const getReadyTimesheetGroupKey = (line) => {
  const candidateId = getLineCandidateId(line);
  const timesheetId = getLineTimesheetId(line);
  if (!candidateId || !timesheetId) return '';
  return `READY_TO_PAY|${candidateId}|${timesheetId}`;
};

const isReadyTimesheetDisplayContextLine = (line) => {
  if (!isPlainObject(line)) return false;
  const nested = getNestedLinePayload(line);
  const section = upperTrim(
    line?.presentation_section || line?.presentationSection ||
    nested?.presentation_section || nested?.presentationSection || ''
  );
  const role = upperTrim(
    line?.presentation_role || line?.presentationRole ||
    nested?.presentation_role || nested?.presentationRole || ''
  );
  const lineType = upperTrim(
    line?.line_type || line?.lineType || nested?.line_type || nested?.lineType || ''
  );
  if (section !== 'READY_TO_PAY' || role !== 'PARENT' || lineType !== 'TIMESHEET_PAYMENT') return false;
  return !!(
    asBool(line?.is_excluded_from_allocation ?? nested?.is_excluded_from_allocation) ||
    (line?.selection_allowed ?? nested?.selection_allowed) === false ||
    (line?.draftable ?? nested?.draftable) === false ||
    (line?.is_ready_for_draft ?? nested?.is_ready_for_draft) === false
  );
};

const getPreviewRowId = (line) => {
  if (!isPlainObject(line)) return '';
  return trimStr(line.preview_row_id || line.previewRowId || line.row_id || line.rowId || line.line_id || line.lineId || line.id);
};

const isPreviewRowSelectionAllowed = (line) => {
  if (!isPlainObject(line)) return false;

  const rowJson = isPlainObject(line.row_json)
    ? line.row_json
    : (isPlainObject(line.rowJson) ? line.rowJson : {});
  const previewContract = isPlainObject(line.preview_contract)
    ? line.preview_contract
    : (isPlainObject(rowJson.preview_contract)
        ? rowJson.preview_contract
        : (isPlainObject(rowJson.previewContract) ? rowJson.previewContract : {}));
  const firstDefined = (...values) => {
    for (const value of values) {
      if (value !== undefined && value !== null && !(typeof value === 'string' && trimStr(value) === '')) return value;
    }
    return undefined;
  };

  const normaliseSelectionSection = (value) => {
    const source = trimStr(value || '');
    if (!source) return '';
    const raw = source
      .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
      .replace(/[^a-zA-Z0-9]+/g, '_')
      .toLowerCase()
      .replace(/^_+|_+$/g, '');
    if (!raw) return '';
    const compact = raw.replace(/_/g, '');
    const readyAliases = new Set([
      'ready', 'ready_to_pay', 'readytopay', 'ready_to_pay_now', 'readytopaynow',
      'ready_preview', 'readypreview', 'ready_preview_line', 'readypreviewline', 'ready_preview_lines', 'readypreviewlines',
      'canonical', 'canonical_preview', 'canonicalpreview', 'canonical_preview_line', 'canonicalpreviewline', 'canonical_preview_lines', 'canonicalpreviewlines',
      'draftable', 'draftable_now', 'draftablenow',
      'preview_row', 'previewrow', 'preview_rows', 'previewrows', 'preview_line', 'previewline', 'preview_lines', 'previewlines',
      'itemisation', 'itemization'
    ]);
    const caseAliases = new Set([
      'cases_resolutions', 'casesresolutions', 'case_resolutions', 'caseresolutions',
      'case_resolution', 'caseresolution', 'case_resolution_state', 'caseresolutionstate',
      'case_resolution_states', 'caseresolutionstates', 'case_state', 'casestate', 'case_states', 'casestates'
    ]);
    const blockedAliases = new Set([
      'blocked', 'blocked_now', 'blockednow', 'blocked_for_pay', 'blockedforpay', 'blocked_for_pay_now', 'blockedforpaynow',
      'blocked_preview', 'blockedpreview', 'blocked_preview_line', 'blockedpreviewline', 'blocked_preview_lines', 'blockedpreviewlines',
      'blocked_item', 'blockeditem', 'blocked_items', 'blockeditems', 'blocked_timesheet', 'blockedtimesheet',
      'do_not_pay', 'donotpay'
    ]);
    const internalAliases = new Set([
      'internal_only', 'internalonly', 'internal', 'hidden',
      'hidden_preview_line', 'hiddenpreviewline', 'hidden_preview_lines', 'hiddenpreviewlines',
      'hidden_indefinite_snooze', 'hiddenindefinitesnooze', 'hidden_indefinite_snoozes', 'hiddenindefinitesnoozes'
    ]);
    if (readyAliases.has(raw) || readyAliases.has(compact)) return 'READY_TO_PAY';
    if (caseAliases.has(raw) || caseAliases.has(compact)) return 'CASES_RESOLUTIONS';
    if (blockedAliases.has(raw) || blockedAliases.has(compact)) return 'BLOCKED_FOR_PAY';
    if (internalAliases.has(raw) || internalAliases.has(compact)) return 'INTERNAL_ONLY';
    return raw.toUpperCase();
  };

  const recoverySelectionOverlay = (() => {
    const overlay = isPlainObject(rowJson.selection_recovery_headroom_v1)
      ? rowJson.selection_recovery_headroom_v1
      : (isPlainObject(line.selection_recovery_headroom_v1)
          ? line.selection_recovery_headroom_v1
          : {});
    const candidateId = trimStr(line.candidate_id || line.candidateId || rowJson.candidate_id || rowJson.candidateId || '');
    const payChannel = upperTrim(line.pay_channel || line.payChannel || rowJson.pay_channel || rowJson.current_pay_method || rowJson.candidate_pay_method || '');
    const lineType = upperTrim(line.line_type || line.lineType || rowJson.line_type || rowJson.item_type || '');
    const parseAmount = (value) => {
      const raw = trimStr(value);
      if (!/^-?[0-9]+(\.[0-9]+)?$/.test(raw)) return null;
      return Math.round(Number(raw) * 100) / 100;
    };
    const selectedPositiveHeadroom = parseAmount(overlay.selected_positive_headroom_ex_vat);
    const recoverableAmount = parseAmount(overlay.recoverable_amount_ex_vat);
    const nominalDueAmount = parseAmount(overlay.nominal_due_amount_ex_vat);
    const rowAmount = parseAmount(line.amount_ex_vat ?? line.amountExVat ?? line.preview_amount_ex_vat ?? line.previewAmountExVat ?? rowJson.amount_ex_vat);
    const physicalSection = normaliseSelectionSection(overlay.physical_section || '');
    const effectiveSection = normaliseSelectionSection(overlay.effective_section || '');
    const overlayDigest = trimStr(overlay.overlay_digest || '');
    const staticRecoveryEligible = overlay.static_recovery_eligible === true
      || ['true', 't', '1', 'yes', 'y', 'on'].includes(trimStr(overlay.static_recovery_eligible).toLowerCase());
    const recoveryLineTypes = new Set([
      'OVERPAYMENT_RECOVERY',
      'MANUAL_DEBT_RECOVERY',
      'PAYMENT_ADVANCE_REPAYMENT',
      'LOAN_REPAYMENT'
    ]);
    const valid = Number(overlay.contract_version) === 1
      && !!candidateId
      && trimStr(overlay.candidate_id || '') === candidateId
      && ['PAYE', 'UMBRELLA'].includes(payChannel)
      && upperTrim(overlay.pay_channel || '') === payChannel
      && recoveryLineTypes.has(lineType)
      && physicalSection === 'BLOCKED_FOR_PAY'
      && effectiveSection === 'READY_TO_PAY'
      && selectedPositiveHeadroom !== null
      && selectedPositiveHeadroom > 0
      && recoverableAmount !== null
      && recoverableAmount > 0
      && recoverableAmount <= selectedPositiveHeadroom
      && nominalDueAmount !== null
      && nominalDueAmount >= recoverableAmount
      && rowAmount !== null
      && rowAmount < 0
      && Math.round(Math.abs(rowAmount) * 100) === Math.round(recoverableAmount * 100)
      && staticRecoveryEligible
      && /^[0-9a-f]{32}$/i.test(overlayDigest)
      && upperTrim(overlay.policy_x_authority_scope || '') === 'PRE_DRAFT_LIVE_TRUTH';
    return valid ? { effective_section: effectiveSection } : null;
  })();

  const sectionSignals = (recoverySelectionOverlay
    ? [
        recoverySelectionOverlay.effective_section,
        line.presentation_section,
        line.presentationSection,
        rowJson.presentation_section,
        rowJson.presentationSection,
        line.resolved_section,
        line.resolvedSection,
        rowJson.resolved_section,
        rowJson.resolvedSection,
        line.requested_section,
        line.requestedSection,
        rowJson.requested_section,
        rowJson.requestedSection
      ]
    : [
        line.presentation_section,
        line.presentationSection,
        rowJson.presentation_section,
        rowJson.presentationSection,
        line.section,
        rowJson.section,
        line.resolved_section,
        line.resolvedSection,
        rowJson.resolved_section,
        rowJson.resolvedSection,
        line.requested_section,
        line.requestedSection,
        rowJson.requested_section,
        rowJson.requestedSection,
        previewContract.section,
        previewContract.presentation_section,
        previewContract.presentationSection
      ]).map(normaliseSelectionSection).filter(Boolean);

  const forbiddenSections = new Set(['CASES_RESOLUTIONS', 'BLOCKED_FOR_PAY', 'INTERNAL_ONLY']);
  if (sectionSignals.some((section) => forbiddenSections.has(section))) return false;


  const selectionState = upperTrim(firstDefined(
    line.selection_state,
    line.selectionState,
    rowJson.selection_state,
    rowJson.selectionState,
    previewContract.selection_state,
    previewContract.selectionState
  ));
  if (selectionState === 'NOT_SELECTABLE' || selectionState === 'SUPERSEDED') return false;

  const status = upperTrim(firstDefined(line.status, line.row_status, line.rowStatus, rowJson.status, rowJson.row_status, rowJson.rowStatus));
  if (status === 'SUPERSEDED' || status === 'BLOCKED' || status === 'ERROR' || status === 'CANCELLED' || status === 'CANCELED') return false;

  const presentationRole = upperTrim(firstDefined(line.presentation_role, line.presentationRole, rowJson.presentation_role, rowJson.presentationRole));
  if (presentationRole === 'HIDDEN' || presentationRole === 'INTERNAL_ONLY') return false;

  const sourceKind = upperTrim(firstDefined(line.source_kind, line.sourceKind, line.source_type, line.sourceType, rowJson.source_kind, rowJson.sourceKind, rowJson.source_type, rowJson.sourceType));
  if (sourceKind === 'INTERNAL_ONLY' || sourceKind === 'TIMESHEET_SNAPSHOT' || sourceKind === 'TIMESHEET_SNAPSHOT_EVIDENCE' || sourceKind === 'RAW_TIMESHEET_SNAPSHOT') return false;

  const rowKey = trimStr(firstDefined(line.row_key, line.rowKey, line.line_key, line.lineKey, rowJson.row_key, rowJson.rowKey, rowJson.line_key, rowJson.lineKey) || '');
  if (rowKey.toLowerCase().startsWith('timesheet_snapshot:')) return false;

  const explicitSelectionAllowed = firstDefined(
    line.selection_allowed,
    line.selectionAllowed,
    rowJson.selection_allowed,
    rowJson.selectionAllowed,
    previewContract.selection_allowed,
    previewContract.selectionAllowed
  );
  const explicitReadyForDraft = firstDefined(
    line.is_ready_for_draft,
    line.isReadyForDraft,
    line.ready_for_draft,
    line.readyForDraft,
    rowJson.is_ready_for_draft,
    rowJson.isReadyForDraft,
    rowJson.ready_for_draft,
    rowJson.readyForDraft,
    previewContract.is_ready_for_draft,
    previewContract.isReadyForDraft
  );
  const explicitDraftable = firstDefined(
    line.draftable,
    line.is_draftable,
    line.isDraftable,
    rowJson.draftable,
    rowJson.is_draftable,
    rowJson.isDraftable,
    previewContract.draftable
  );
  const currentReadyContract = sectionSignals.some((section) => section === 'READY_TO_PAY')
    && asBool(explicitSelectionAllowed)
    && asBool(explicitReadyForDraft)
    && asBool(explicitDraftable);

  const readinessState = normaliseSelectionSection(firstDefined(
    line.readiness_state,
    line.readinessState,
    rowJson.readiness_state,
    rowJson.readinessState
  ));
  // A resolved case may retain its historical CASES_RESOLUTIONS readiness
  // label after the database has promoted it to a current READY_TO_PAY row.
  // The current server-owned selection/draft contract wins; the backend
  // still revalidates the exact row before any draft is created.
  if (forbiddenSections.has(readinessState) && !currentReadyContract) return false;

  const lineType = normaliseSelectionSection(firstDefined(line.line_type, line.lineType, rowJson.line_type, rowJson.lineType));
  if (lineType === 'BLOCKED_FOR_PAY' || lineType === 'CASES_RESOLUTIONS' || lineType === 'INTERNAL_ONLY') return false;

  if (asBool(firstDefined(line.internal_only, line.internalOnly, rowJson.internal_only, rowJson.internalOnly))) return false;
  if (asBool(firstDefined(line.is_excluded_from_allocation, line.isExcludedFromAllocation, rowJson.is_excluded_from_allocation, rowJson.isExcludedFromAllocation))) return false;
  if (asBool(firstDefined(line.do_not_pay, line.doNotPay, rowJson.do_not_pay, rowJson.doNotPay))) return false;
  if (asBool(firstDefined(line.case_is_blocked, line.caseIsBlocked, rowJson.case_is_blocked, rowJson.caseIsBlocked))) return false;

  if (explicitSelectionAllowed !== undefined && !asBool(explicitSelectionAllowed)) return false;

  if (explicitReadyForDraft !== undefined && !asBool(explicitReadyForDraft)) return false;

  if (explicitDraftable !== undefined && !asBool(explicitDraftable)) return false;

  const hasReadySection = sectionSignals.some((section) => section === 'READY_TO_PAY') || readinessState === 'READY_TO_PAY';
  const hasStrongReadySignal = hasReadySection
    || status === 'READY'
    || readinessState === 'READY'
    || readinessState === 'DRAFTABLE'
    || asBool(explicitReadyForDraft)
    || asBool(explicitDraftable);
  if (!hasStrongReadySignal) return false;

  return !!getPreviewRowId(line);
};

const normaliseWorkbenchPayRoute = (value) => {
  const raw = upperTrim(value).replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  if (['PAYE', 'PAYE_ONLY', 'PAYE_CHANNEL'].includes(raw)) return 'PAYE';
  if (['UMBRELLA', 'UMBRELLA_ONLY', 'UMBRELLA_CHANNEL', 'NON_PAYE', 'NONPAYE'].includes(raw)) return 'UMBRELLA';
  return '';
};

const collectWorkbenchFilterIds = (rowLike, keyNames) => {
  const out = new Set();
  const keys = new Set(keyNames);
  const visit = (value, depth = 0) => {
    if (depth > 6 || value == null) return;
    if (Array.isArray(value)) {
      for (const item of value) visit(item, depth + 1);
      return;
    }
    if (!isPlainObject(value)) return;
    for (const [key, child] of Object.entries(value)) {
      if (keys.has(key)) {
        const id = trimStr(child);
        if (id) out.add(id);
      }
      if (Array.isArray(child) || isPlainObject(child)) visit(child, depth + 1);
    }
  };
  visit(rowLike);
  return out;
};

const workbenchEffectiveRouteKeys = new Set([
  'pay_channel', 'payChannel', 'candidate_pay_method', 'candidatePayMethod',
  'current_pay_method', 'currentPayMethod', 'pay_method', 'payMethod'
]);

const workbenchSourceRouteKeys = new Set([
  'source_pay_method', 'sourcePayMethod', 'from_pay_method', 'fromPayMethod', 'previous_pay_method', 'previousPayMethod',
  'timesheet_pay_method', 'timesheetPayMethod', 'ts_pay_method', 'tsPayMethod', 'frozen_source_pay_method', 'frozenSourcePayMethod',
  'source_pay_channel', 'sourcePayChannel'
]);

const collectWorkbenchRouteSignals = (rowLike) => {
  const resolutionTarget = new Set();
  const effective = new Set();
  const source = new Set();
  const visit = (value, depth = 0) => {
    if (depth > 7 || value == null) return;
    if (Array.isArray(value)) {
      for (const item of value) visit(item, depth + 1);
      return;
    }
    if (!isPlainObject(value)) return;
    for (const [key, child] of Object.entries(value)) {
      if (workbenchResolutionTargetRouteKeys.has(key)) {
        const route = normaliseWorkbenchPayRoute(child);
        if (route) resolutionTarget.add(route);
      }
      if (workbenchEffectiveRouteKeys.has(key)) {
        const route = normaliseWorkbenchPayRoute(child);
        if (route) effective.add(route);
      }
      if (workbenchSourceRouteKeys.has(key)) {
        const route = normaliseWorkbenchPayRoute(child);
        if (route) source.add(route);
      }
      if (Array.isArray(child) || isPlainObject(child)) visit(child, depth + 1);
    }
  };
  visit(rowLike);
  return { resolutionTarget, effective, source };
};

const rowMatchesCandidateClientFilters = (rowLike) => {
  const candidateIds = collectWorkbenchFilterIds(rowLike, ['candidate_id', 'candidateId']);
  const clientIds = collectWorkbenchFilterIds(rowLike, ['client_id', 'clientId']);
  if (candFilterId) {
    if (candidateIds.size > 0 && !candidateIds.has(candFilterId)) return false;
    if (candidateIds.size <= 0 && sessionCandidateFilterId !== candFilterId) return false;
  }
  if (clientFilterId) {
    if (clientIds.size > 0 && !clientIds.has(clientFilterId)) return false;
    if (clientIds.size <= 0 && sessionClientFilterId !== clientFilterId) return false;
  }
  return true;
};

const rowMatchesPayRouteFilter = (rowLike, sectionKind = '') => {
  if (draftScope === 'ALL') return true;
  const signals = collectWorkbenchRouteSignals(rowLike);
  const isCaseResolution = upperTrim(sectionKind) === 'CASES_RESOLUTIONS';
  if (isCaseResolution) {
    // A route-changing case is relevant to its proposed/resolved target.
    // Generic current/visible route metadata is considered only when no
    // explicit target is present; source/from route is the final fallback.
    // This keeps Umbrella -> PAYE visible for PAYE and PAYE -> Umbrella
    // visible for Umbrella even when a top-level pay_channel is the source.
    if (signals.resolutionTarget.size > 0) return signals.resolutionTarget.has(draftScope);
    if (signals.effective.size > 0) return signals.effective.has(draftScope);
    return signals.source.has(draftScope);
  }
  if (signals.effective.size > 0) return signals.effective.has(draftScope);
  if (signals.resolutionTarget.size > 0) return signals.resolutionTarget.has(draftScope);
  return signals.source.has(draftScope);
};

const rowMatchesActivePayFilters = (rowLike, sectionKind = '') => (
  rowMatchesCandidateClientFilters(rowLike) && rowMatchesPayRouteFilter(rowLike, sectionKind)
);

const parseBlockerCodes = (raw) => {
  if (Array.isArray(raw)) return raw.map((x) => upperTrim(x)).filter(Boolean);
  if (typeof raw === 'string') {
    const s = raw.trim();
    if (!s) return [];
    try {
      const j = JSON.parse(s);
      if (Array.isArray(j)) return j.map((x) => upperTrim(x)).filter(Boolean);
    } catch {}
    return s.split(',').map((x) => upperTrim(x)).filter(Boolean);
  }
  return [];
};

const getBankPayeeContext = (obj) => {
  return isPlainObject(obj?.payee_context) ? obj.payee_context : {};
};

const hasBankBlockerContract = (obj) => {
  if (!isPlainObject(obj)) return false;
  const payeeContext = getBankPayeeContext(obj);
  return ['blockers', 'blocked_reason_codes', 'blockedReasonCodes'].some((key) => (
    Object.prototype.hasOwnProperty.call(obj, key) ||
    Object.prototype.hasOwnProperty.call(payeeContext, key)
  ));
};

const getBankBlockerCodes = (obj) => {
  if (!isPlainObject(obj)) return [];
  const payeeContext = getBankPayeeContext(obj);
  return Array.from(new Set([
    ...parseBlockerCodes(obj.blockers),
    ...parseBlockerCodes(obj.blocked_reason_codes),
    ...parseBlockerCodes(obj.blockedReasonCodes),
    ...parseBlockerCodes(payeeContext.blockers),
    ...parseBlockerCodes(payeeContext.blocked_reason_codes),
    ...parseBlockerCodes(payeeContext.blockedReasonCodes)
  ]));
};

const getExactBankTargetHash = (obj, fallbackMeta = null) => {
  const payeeContext = getBankPayeeContext(obj);
  const fallbackPayeeContext = getBankPayeeContext(fallbackMeta);
  return trimStr(
    obj?.bank_details_hash ||
    obj?.payee_bank_hash ||
    obj?.bank_details_hash_snapshot ||
    obj?.snapshot_bank_details_hash ||
    payeeContext.bank_details_hash ||
    payeeContext.payee_bank_hash ||
    payeeContext.bank_details_hash_snapshot ||
    payeeContext.snapshot_bank_details_hash ||
    fallbackMeta?.bank_details_hash ||
    fallbackMeta?.payee_bank_hash ||
    fallbackMeta?.bank_details_hash_snapshot ||
    fallbackMeta?.snapshot_bank_details_hash ||
    fallbackPayeeContext.bank_details_hash ||
    fallbackPayeeContext.payee_bank_hash ||
    fallbackPayeeContext.bank_details_hash_snapshot ||
    fallbackPayeeContext.snapshot_bank_details_hash ||
    ''
  );
};

const getLineBankActionMeta = (line) => {
  if (!isPlainObject(line)) return null;
  const candidateId = trimStr(line?.candidate_id);
  const candidateMeta = candidateMetaById.get(candidateId) || null;
  const payeeContext = getBankPayeeContext(line);
  const lineHasBlockerContract = hasBankBlockerContract(line);

  return {
    candidate_id: candidateId || trimStr(candidateMeta?.candidate_id || ''),
    preview_row_id: getPreviewRowId(line),
    display_name: trimStr(line?.display_name || candidateMeta?.display_name || ''),
    tms_ref: trimStr(line?.tms_ref || candidateMeta?.tms_ref || ''),
    current_pay_method: upperTrim(line?.pay_channel || line?.current_pay_method || candidateMeta?.current_pay_method || ''),
    is_ready_for_draft: Object.prototype.hasOwnProperty.call(line, 'is_ready_for_draft')
      ? asBool(line?.is_ready_for_draft)
      : asBool(candidateMeta?.is_ready_for_draft),
    blockers: lineHasBlockerContract ? getBankBlockerCodes(line) : getBankBlockerCodes(candidateMeta),
    payee_entity_kind: upperTrim(line?.payee_entity_kind || payeeContext.payee_entity_kind || candidateMeta?.payee_entity_kind || ''),
    payee_entity_id: trimStr(line?.payee_entity_id || payeeContext.payee_entity_id || candidateMeta?.payee_entity_id || ''),
    bank_details_hash: getExactBankTargetHash(line, candidateMeta),
    payee_bank_hash: trimStr(line?.payee_bank_hash || payeeContext.payee_bank_hash || candidateMeta?.payee_bank_hash || ''),
    bank_details_hash_snapshot: trimStr(line?.bank_details_hash_snapshot || payeeContext.bank_details_hash_snapshot || candidateMeta?.bank_details_hash_snapshot || ''),
    snapshot_bank_details_hash: trimStr(line?.snapshot_bank_details_hash || payeeContext.snapshot_bank_details_hash || candidateMeta?.snapshot_bank_details_hash || ''),
    name_check_status: upperTrim(line?.name_check_status || payeeContext.name_check_status || candidateMeta?.name_check_status || ''),
    name_check_has_override: Object.prototype.hasOwnProperty.call(line, 'name_check_has_override')
      ? asBool(line?.name_check_has_override)
      : (Object.prototype.hasOwnProperty.call(payeeContext, 'name_check_has_override')
          ? asBool(payeeContext.name_check_has_override)
          : asBool(candidateMeta?.name_check_has_override)),
    payee_map_present: Object.prototype.hasOwnProperty.call(line, 'payee_map_present')
      ? asBool(line?.payee_map_present)
      : (Object.prototype.hasOwnProperty.call(payeeContext, 'payee_map_present')
          ? asBool(payeeContext.payee_map_present)
          : asBool(candidateMeta?.payee_map_present))
  };
};

const renderAcceptBankDetailsButton = (meta) => {
  const entityKind = upperTrim(meta?.payee_entity_kind || '');
  const entityId = trimStr(meta?.payee_entity_id || '');
  const blockers = Array.isArray(meta?.blockers) ? meta.blockers : [];
  const hasOverride = asBool(meta?.name_check_has_override);
  const candidateId = trimStr(meta?.candidate_id || '');
  const previewRowId = trimStr(meta?.preview_row_id || '');
  const nameCheckStatus = upperTrim(meta?.name_check_status || '');
  const bankDetailsHash = trimStr(
    meta?.bank_details_hash ||
    meta?.payee_bank_hash ||
    meta?.bank_details_hash_snapshot ||
    meta?.snapshot_bank_details_hash ||
    ''
  );

  const validEntity = !!entityKind && !!entityId && (entityKind === 'CANDIDATE' || entityKind === 'UMBRELLA');
  const hasExactTargetHash = !!bankDetailsHash;
  const hasBankMissing = blockers.includes('BLOCKED_BANK_DETAILS');
  const hasUmbrellaInactive = blockers.includes('BLOCKED_UMBRELLA_INACTIVE');
  const hasNameBlock = blockers.includes('BLOCKED_NAME_CHECK');
  const hasMapBlock = blockers.includes('BLOCKED_NO_PAYEE_MAP');
  const nameGateSatisfied = hasOverride || nameCheckStatus === 'PASS';
  const nameMismatchLike = ['FAIL', 'NEAR_MATCH', 'UNAVAILABLE'].includes(nameCheckStatus);

  // Missing bank details and inactive umbrellas have their own primary fixes.
  // Do not offer provider/payee-map setup for those states.
  if (hasBankMissing || hasUmbrellaInactive) return '';

  const canAccept = validEntity && hasExactTargetHash && hasNameBlock && !hasOverride && nameMismatchLike;
  const canRunNameCheck = validEntity && hasExactTargetHash && hasNameBlock && !nameGateSatisfied && !nameMismatchLike;
  const canEnsurePayeeMap = validEntity && hasExactTargetHash && hasMapBlock && nameGateSatisfied && !canAccept && !canRunNameCheck;

  if (!canAccept && !canRunNameCheck && !canEnsurePayeeMap) return '';

  if (canAccept) {
    return `
      <button
        type="button"
        class="btn btn-xs btn-outline"
        data-action="banking:pay:acceptBankDetails"
        data-entity-kind="${enc(entityKind)}"
        data-entity-id="${enc(entityId)}"
        data-bank-details-hash="${enc(bankDetailsHash)}"
        ${railProvider ? `data-provider="${enc(railProvider)}"` : ''}
        ${railEnv ? `data-env="${enc(railEnv)}"` : ''}
        data-candidate-id="${enc(candidateId)}"
        ${previewRowId ? `data-preview-row-id="${enc(previewRowId)}"` : ''}
        ${getCandidateActionDisabledAttrs(candidateId, 'Accept these bank details for payment after review (a reason is required and this is fully audited).')}
      >Accept bank details</button>
    `;
  }

  if (canRunNameCheck) {
    return `
      <button
        type="button"
        class="btn btn-xs btn-outline"
        data-action="banking:pay:runBankNameCheck"
        data-entity-kind="${enc(entityKind)}"
        data-entity-id="${enc(entityId)}"
        data-bank-details-hash="${enc(bankDetailsHash)}"
        ${railProvider ? `data-provider="${enc(railProvider)}"` : ''}
        ${railEnv ? `data-env="${enc(railEnv)}"` : ''}
        data-candidate-id="${enc(candidateId)}"
        ${previewRowId ? `data-preview-row-id="${enc(previewRowId)}"` : ''}
        ${getCandidateActionDisabledAttrs(candidateId, 'Run bank/name check and payee readiness for this payee.')}
      >Run bank/name check</button>
    `;
  }

  return `
    <button
      type="button"
      class="btn btn-xs btn-outline"
      data-action="banking:pay:ensurePayeeMap"
      data-entity-kind="${enc(entityKind)}"
      data-entity-id="${enc(entityId)}"
      data-bank-details-hash="${enc(bankDetailsHash)}"
      ${railProvider ? `data-provider="${enc(railProvider)}"` : ''}
      ${railEnv ? `data-env="${enc(railEnv)}"` : ''}
      data-candidate-id="${enc(candidateId)}"
      ${previewRowId ? `data-preview-row-id="${enc(previewRowId)}"` : ''}
      ${getCandidateActionDisabledAttrs(candidateId, 'Set up this bank account with the payment provider so it can move into Ready to Pay.')}
    >Set up bank account</button>
  `;
};

const getSnoozeInfo = (obj) => {
  const ss = (obj && typeof obj.snooze_state === 'object') ? obj.snooze_state : {};
  const state = upperTrim(ss.state || obj?.snooze_state || obj?.blocked_snooze_state || '');
  const snoozeUntil = trimStr(ss.snooze_until_date || obj?.snooze_until_date || '');
  const snoozeId = trimStr(ss.snooze_id || obj?.snooze_id || obj?.active_snooze_id || '');
  const note = trimStr(ss.note || ss.snooze_note || obj?.note || obj?.snooze_note || obj?.active_snooze_note || '');
  const hasActive = !!state && state !== 'NONE' && state !== 'NOT_SNOOZED' && state !== 'CLEARED';
  return {
    hasActive,
    isIndefinite: hasActive && !snoozeUntil,
    isDated: hasActive && !!snoozeUntil,
    state,
    snoozeUntil,
    snoozeId,
    note
  };
};

const isHiddenDisplayRow = (line) => {
  const presentationRole = upperTrim(line?.presentation_role || line?.presentationRole || '');
  const presentationSection = getLinePresentationSection(line);
  const readinessState = upperTrim(line?.readiness_state || line?.readinessState || '');
  return !!(
    presentationRole === 'HIDDEN' ||
    presentationSection === 'HIDDEN' ||
    readinessState === 'HIDDEN' ||
    asBool(line?.is_hidden) ||
    asBool(line?.hidden) ||
    asBool(line?.hidden_indefinite_snooze) ||
    asBool(line?.is_indefinitely_snoozed)
  );
};

const groupEntriesByCandidate = (arr) => {
  const map = new Map();
  for (const entry of arr) {
    const cid = trimStr(entry.candidate_id);
    if (!cid) continue;
    if (!map.has(cid)) {
      map.set(cid, {
        candidate: candidateMetaById.get(cid) || {
          candidate_id: cid,
          display_name: trimStr(entry?.candidate_display_name || ''),
          tms_ref: trimStr(entry?.candidate_tms_ref || ''),
          current_pay_method: upperTrim(entry?.current_pay_method || '')
        },
        entries: []
      });
    }
    map.get(cid).entries.push(deep(entry));
  }
  return Array.from(map.entries()).map(([candidateId, val]) => ({
    candidate_id: candidateId,
    candidate: val.candidate,
    entries: val.entries
  }));
};

const buildCaseResolutionDisplayState = ({ previewRoot, candidateRows, cache, caseLines }) => {
  const preview = (previewRoot && typeof previewRoot === 'object') ? previewRoot : {};
  const cacheObj = (cache && typeof cache === 'object') ? cache : {};
  const casePreviewRows = asArray(caseLines).filter((line) => isPlainObject(line));

  const firstNonBlankString = (...values) => {
    for (const value of values) {
      const s = trimStr(value);
      if (s) return s;
    }
    return '';
  };
  const firstDefinedValue = (...values) => {
    for (const value of values) {
      if (value === undefined || value === null) continue;
      if (typeof value === 'string' && !trimStr(value)) continue;
      return value;
    }
    return undefined;
  };
  const firstPlainObject = (...values) => {
    for (const value of values) {
      if (isPlainObject(value)) return value;
    }
    return null;
  };
  const firstArrayOfObjects = (...values) => {
    for (const value of values) {
      const arr = asArray(value).filter((item) => isPlainObject(item));
      if (arr.length) return arr.map((item) => deep(item));
    }
    return [];
  };
  const hasActionableSuggestedResolution = (components) => asArray(components).some((component) => {
    if (!isPlainObject(component)) return false;
    const requiresResolution = asBool(firstDefinedValue(
      component.requires_resolution,
      component.needs_resolution,
      component.resolution_required
    ));
    if (!requiresResolution) return false;

    const explicitActionable = firstDefinedValue(
      component.is_actionable_resolution_row,
      component.actionable_resolution_row,
      component.is_actionable
    );
    if (explicitActionable !== undefined && !asBool(explicitActionable)) return false;

    const suggestedPayload = firstPlainObject(
      component.suggested_resolution_payload_json,
      component.suggested_resolution_payload,
      component.suggested_payload_json
    );
    const suggestedResult = firstPlainObject(
      component.suggested_resolution_result_json,
      component.suggested_resolution_result,
      component.suggested_result_json
    );
    const hasSuggestedFlag = asBool(firstDefinedValue(
      component.has_suggested_resolution,
      component.is_fresh_suggested_resolution,
      component.suggested_resolution_available
    ));

    const sourceUnits = Number(component.source_units);
    const sourceRate = Number(component.source_rate);
    const sourceChargeRate = Number(component.source_charge_rate);
    const componentKeyType = upperTrim(component.component_key_type);
    const bucketCode = upperTrim(
      component.bucket_code ||
      component.source_basis_json?.bucket_code ||
      ''
    );
    const hasManualRateBasis = (
      ['TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE', 'PAY_CODE', 'ADDITIONAL_PAY_CODE', 'ADDITIONAL_UNIT', 'ADDITIONAL_UNITS'].includes(componentKeyType) &&
      Number.isFinite(sourceUnits) &&
      Math.abs(sourceUnits) > 0.000000001 &&
      Number.isFinite(sourceRate) &&
      Number.isFinite(sourceChargeRate) &&
      (!['TS_DAY', 'TS_TOTAL'].includes(componentKeyType) || !!bucketCode)
    );

    return (
      ((hasSuggestedFlag || !!suggestedPayload || !!suggestedResult)
        && (!!suggestedPayload || !!suggestedResult))
      || hasManualRateBasis
    );
  });
  const makeScopedKey = (prefix, candidateId, value) => {
    const candidateIdText = trimStr(candidateId);
    const valueText = trimStr(value);
    return (candidateIdText && valueText) ? `${prefix}|${candidateIdText}|${valueText}` : '';
  };
  const makeCandidateTimesheetKey = (candidateId, timesheetId) => {
    const candidateIdText = trimStr(candidateId);
    const timesheetIdText = trimStr(timesheetId);
    return (candidateIdText && timesheetIdText) ? `TIMESHEET|${candidateIdText}|${timesheetIdText}` : '';
  };
  const makeEntryIdentityKey = (entry) => {
    const candidateId = trimStr(entry?.candidate_id);
    const caseKey = trimStr(entry?.case_key);
    const financeCaseId = trimStr(entry?.finance_case_id);
    const linkedTimesheetId = trimStr(entry?.linked_timesheet_id);
    const caseType = upperTrim(entry?.case_type);
    if (candidateId && caseKey) return `CASE_KEY|${candidateId}|${caseKey}`;
    if (candidateId && financeCaseId) return `FINANCE_CASE|${candidateId}|${financeCaseId}`;
    if (candidateId && linkedTimesheetId && caseType) return `TIMESHEET_CASE|${candidateId}|${linkedTimesheetId}|${caseType}`;
    if (candidateId && linkedTimesheetId) return `TIMESHEET|${candidateId}|${linkedTimesheetId}`;
    if (caseKey) return `CASE_KEY_ONLY|${caseKey}`;
    if (financeCaseId) return `FINANCE_CASE_ONLY|${financeCaseId}`;
    return '';
  };
  const unwrapRawCase = (rawValue) => {
    const rawObj = isPlainObject(rawValue) ? rawValue : null;
    if (!rawObj) return null;
    if (isPlainObject(rawObj.case)) return rawObj.case;
    return rawObj;
  };
  const buildOverlayedDisplayEntry = (entry, line) => {
    const displayEntry = deep(entry);
    const previewLine = isPlainObject(line) ? line : {};
    const lineResolutionSummary = firstPlainObject(
      previewLine.case_resolution_summary,
      previewLine.caseResolutionSummary,
      previewLine.row_json?.case_resolution_summary,
      previewLine.row_json?.caseResolutionSummary,
      previewLine.rowJson?.case_resolution_summary,
      previewLine.rowJson?.caseResolutionSummary
    );
    const lineComponentSources = [
      previewLine.case_components,
      previewLine.caseComponents,
      previewLine.row_json?.case_components,
      previewLine.row_json?.caseComponents,
      previewLine.rowJson?.case_components,
      previewLine.rowJson?.caseComponents
    ];
    const lineComponentsProvided = lineComponentSources.some((value) => Array.isArray(value));
    const lineComponents = firstArrayOfObjects(...lineComponentSources);
    const lineAmount = getLineSectionAmount(previewLine);
    const candidateDisplayName = trimStr(firstNonBlankString(previewLine.display_name, displayEntry.candidate_display_name));
    const candidateTmsRef = trimStr(firstNonBlankString(previewLine.tms_ref, displayEntry.candidate_tms_ref));
    const clientName = trimStr(firstNonBlankString(previewLine.client_name, previewLine.raw_case?.client_name, displayEntry.client_name, displayEntry.raw_case?.client_name));
    displayEntry.line_id = trimStr(firstNonBlankString(previewLine.line_id, previewLine.preview_row_id, previewLine.row_id, previewLine.id, displayEntry.line_id));
    displayEntry.presentation_section = upperTrim(firstNonBlankString(previewLine.presentation_section, displayEntry.presentation_section));
    displayEntry.presentation_reason = trimStr(firstNonBlankString(previewLine.presentation_reason, displayEntry.presentation_reason));
    if (lineResolutionSummary) {
      displayEntry.case_resolution_summary = deep(lineResolutionSummary);
      displayEntry.case_type = upperTrim(firstNonBlankString(previewLine.case_type, lineResolutionSummary.case_type, displayEntry.case_type));
      displayEntry.resolution_family = upperTrim(firstNonBlankString(previewLine.resolution_family, lineResolutionSummary.resolution_family, displayEntry.resolution_family));
      displayEntry.resolution_action_label = trimStr(firstNonBlankString(previewLine.resolution_action_label, lineResolutionSummary.resolution_action_label, displayEntry.resolution_action_label));
      displayEntry.case_needs_resolution = asBool(firstDefinedValue(previewLine.case_needs_resolution, lineResolutionSummary.case_needs_resolution, displayEntry.case_needs_resolution));
      displayEntry.case_resolution_satisfied_now = asBool(firstDefinedValue(previewLine.case_resolution_satisfied_now, lineResolutionSummary.case_resolution_satisfied_now, displayEntry.case_resolution_satisfied_now));
      displayEntry.unresolved_taxable_count = Math.trunc(toNum(firstDefinedValue(previewLine.unresolved_taxable_count, lineResolutionSummary.unresolved_taxable_count, displayEntry.unresolved_taxable_count), 0));
      displayEntry.stale_count = Math.trunc(toNum(firstDefinedValue(previewLine.stale_count, lineResolutionSummary.stale_count, displayEntry.stale_count), 0));
      displayEntry.is_mixed_case = asBool(firstDefinedValue(previewLine.is_mixed_case, lineResolutionSummary.is_mixed_case, displayEntry.is_mixed_case));
      displayEntry.linked_resolution_scope_json = firstDefinedValue(previewLine.linked_resolution_scope_json, lineResolutionSummary.linked_resolution_scope_json, displayEntry.linked_resolution_scope_json);
    }
    if (lineComponentsProvided) displayEntry.components = lineComponents;
    displayEntry.has_actionable_suggested_resolution = hasActionableSuggestedResolution(displayEntry.components);
    displayEntry.resolution_action_requires_actionable_components = !!lineResolutionSummary
      && upperTrim(displayEntry.resolution_family) === 'BUCKETED';
    if (lineAmount !== undefined) {
      displayEntry.case_amount = toNum(lineAmount, displayEntry.case_amount || 0);
      displayEntry.amount_ex_vat = lineAmount;
    }
    displayEntry.week_ending_date = trimStr(firstNonBlankString(previewLine.week_ending_date, displayEntry.week_ending_date));
    displayEntry.linked_shift_date = trimStr(firstNonBlankString(previewLine.linked_shift_date, displayEntry.linked_shift_date));
    displayEntry.client_name = clientName;
    displayEntry.candidate_display_name = candidateDisplayName;
    displayEntry.display_name = candidateDisplayName;
    displayEntry.candidate_tms_ref = candidateTmsRef;
    displayEntry.tms_ref = candidateTmsRef;
    displayEntry.candidate = isPlainObject(displayEntry.candidate) ? displayEntry.candidate : {};
    displayEntry.candidate.candidate_id = trimStr(firstNonBlankString(displayEntry.candidate?.candidate_id, displayEntry.candidate_id));
    displayEntry.candidate.display_name = candidateDisplayName || trimStr(displayEntry.candidate?.display_name || '');
    displayEntry.candidate.tms_ref = candidateTmsRef || trimStr(displayEntry.candidate?.tms_ref || '');
    displayEntry.candidate.current_pay_method = upperTrim(firstNonBlankString(previewLine.pay_channel, displayEntry.candidate?.current_pay_method, displayEntry.current_pay_method));
    displayEntry.raw_case = isPlainObject(displayEntry.raw_case) ? displayEntry.raw_case : {};
    if (clientName) displayEntry.raw_case.client_name = clientName;
    return displayEntry;
  };

  const caseEntries = [];
  const seenEntryKeys = new Set();
  const caseEntryByCaseKey = new Map();
  const caseEntryByScopedCaseKey = new Map();
  const caseEntryByFinanceCaseId = new Map();
  const caseEntryByScopedFinanceCaseId = new Map();
  const caseEntryByCandidateTimesheet = new Map();

  const normalizeCaseEntry = (rawEntry, sourceCandidate = null) => {
    const entry = isPlainObject(rawEntry) ? rawEntry : {};
    const nestedCase = firstPlainObject(entry.case, entry.case_state, entry.state);
    const rawCaseEnvelope = firstPlainObject(entry.raw_case, nestedCase?.raw_case);
    const rawCase = unwrapRawCase(rawCaseEnvelope);
    const resolutionSummary = firstPlainObject(
      entry.case_resolution_summary,
      entry.caseResolutionSummary,
      nestedCase?.case_resolution_summary,
      nestedCase?.caseResolutionSummary,
      rawCase?.case_resolution_summary,
      rawCase?.caseResolutionSummary
    );
    const components = firstArrayOfObjects(
      entry.components,
      entry.case_components,
      entry.caseComponents,
      entry.component_states,
      entry.component_resolution_states,
      entry.preview_components,
      nestedCase?.components,
      nestedCase?.case_components,
      nestedCase?.caseComponents,
      nestedCase?.component_states,
      nestedCase?.component_resolution_states,
      nestedCase?.preview_components,
      rawCase?.components,
      rawCase?.case_components,
      rawCase?.caseComponents,
      rawCase?.component_states,
      rawCase?.component_resolution_states,
      rawCase?.preview_components
    );
    const candidateId = trimStr(firstNonBlankString(
      entry.candidate_id,
      nestedCase?.candidate_id,
      rawCase?.candidate_id,
      resolutionSummary?.candidate_id,
      sourceCandidate?.candidate_id
    ));
    if (!candidateId) return null;

    const candidateMeta = candidateMetaById.get(candidateId) || null;
    const caseKey = trimStr(firstNonBlankString(entry.case_key, nestedCase?.case_key, rawCase?.case_key, resolutionSummary?.case_key));
    const financeCaseId = trimStr(firstNonBlankString(entry.finance_case_id, nestedCase?.finance_case_id, rawCase?.finance_case_id, resolutionSummary?.finance_case_id));
    const linkedTimesheetId = trimStr(firstNonBlankString(
      entry.linked_timesheet_id,
      entry.timesheet_id,
      nestedCase?.linked_timesheet_id,
      nestedCase?.timesheet_id,
      rawCase?.linked_timesheet_id,
      rawCase?.timesheet_id,
      resolutionSummary?.linked_timesheet_id,
      resolutionSummary?.timesheet_id
    ));
    if (!caseKey && !financeCaseId && !linkedTimesheetId) return null;

    const normalized = {
      candidate_id: candidateId,
      candidate_display_name: trimStr(firstNonBlankString(
        entry.candidate_display_name,
        entry.display_name,
        nestedCase?.candidate_display_name,
        nestedCase?.display_name,
        rawCase?.candidate_display_name,
        rawCase?.display_name,
        sourceCandidate?.display_name,
        candidateMeta?.display_name
      )),
      candidate_tms_ref: trimStr(firstNonBlankString(
        entry.candidate_tms_ref,
        entry.tms_ref,
        nestedCase?.candidate_tms_ref,
        nestedCase?.tms_ref,
        rawCase?.candidate_tms_ref,
        rawCase?.tms_ref,
        sourceCandidate?.tms_ref,
        candidateMeta?.tms_ref
      )),
      current_pay_method: upperTrim(firstNonBlankString(
        entry.current_pay_method,
        entry.pay_channel,
        nestedCase?.current_pay_method,
        nestedCase?.pay_channel,
        rawCase?.current_pay_method,
        rawCase?.pay_channel,
        sourceCandidate?.current_pay_method,
        candidateMeta?.current_pay_method
      )),
      finance_case_id: financeCaseId,
      case_key: caseKey,
      case_type: upperTrim(firstNonBlankString(entry.case_type, nestedCase?.case_type, rawCase?.case_type, resolutionSummary?.case_type)),
      resolution_family: upperTrim(firstNonBlankString(entry.resolution_family, nestedCase?.resolution_family, rawCase?.resolution_family, resolutionSummary?.resolution_family)),
      resolution_action_label: trimStr(firstNonBlankString(entry.resolution_action_label, nestedCase?.resolution_action_label, rawCase?.resolution_action_label, resolutionSummary?.resolution_action_label)),
      case_needs_resolution: asBool(firstDefinedValue(entry.case_needs_resolution, nestedCase?.case_needs_resolution, rawCase?.case_needs_resolution, resolutionSummary?.case_needs_resolution, entry.needs_resolution, nestedCase?.needs_resolution, rawCase?.needs_resolution, resolutionSummary?.needs_resolution)),
      case_resolution_satisfied_now: asBool(firstDefinedValue(entry.case_resolution_satisfied_now, nestedCase?.case_resolution_satisfied_now, rawCase?.case_resolution_satisfied_now, resolutionSummary?.case_resolution_satisfied_now)),
      linked_timesheet_id: linkedTimesheetId,
      week_ending_date: trimStr(firstNonBlankString(entry.week_ending_date, nestedCase?.week_ending_date, rawCase?.week_ending_date)),
      linked_shift_date: trimStr(firstNonBlankString(entry.linked_shift_date, nestedCase?.linked_shift_date, rawCase?.linked_shift_date)),
      blocked_reason: trimStr(firstNonBlankString(entry.blocked_reason, entry.reason_text, nestedCase?.blocked_reason, nestedCase?.reason_text, rawCase?.blocked_reason, rawCase?.reason_text)),
      case_amount: toNum(firstDefinedValue(entry.case_amount, entry.amount_ex_vat, nestedCase?.case_amount, nestedCase?.amount_ex_vat, rawCase?.case_amount, rawCase?.amount_ex_vat), 0),
      unresolved_taxable_count: Math.trunc(toNum(firstDefinedValue(entry.unresolved_taxable_count, nestedCase?.unresolved_taxable_count, rawCase?.unresolved_taxable_count, resolutionSummary?.unresolved_taxable_count), 0)),
      stale_count: Math.trunc(toNum(firstDefinedValue(entry.stale_count, nestedCase?.stale_count, rawCase?.stale_count, resolutionSummary?.stale_count), 0)),
      is_mixed_case: asBool(firstDefinedValue(entry.is_mixed_case, nestedCase?.is_mixed_case, rawCase?.is_mixed_case, resolutionSummary?.is_mixed_case)),
      excluded_from_run: asBool(firstDefinedValue(entry.excluded_from_run, entry.exclude_from_run, nestedCase?.excluded_from_run, nestedCase?.exclude_from_run, rawCase?.excluded_from_run, rawCase?.exclude_from_run, resolutionSummary?.excluded_from_run)),
      linked_resolution_scope_json: firstDefinedValue(entry.linked_resolution_scope_json, nestedCase?.linked_resolution_scope_json, rawCase?.linked_resolution_scope_json, resolutionSummary?.linked_resolution_scope_json),
      taxable_manual_debt_resolution: firstDefinedValue(entry.taxable_manual_debt_resolution, nestedCase?.taxable_manual_debt_resolution, rawCase?.taxable_manual_debt_resolution),
      components,
      case_resolution_summary: isPlainObject(resolutionSummary) ? deep(resolutionSummary) : null,
      has_actionable_suggested_resolution: hasActionableSuggestedResolution(components),
      resolution_action_requires_actionable_components: !!resolutionSummary
        && upperTrim(firstNonBlankString(entry.resolution_family, nestedCase?.resolution_family, rawCase?.resolution_family, resolutionSummary?.resolution_family)) === 'BUCKETED',
      presentation_section: upperTrim(firstNonBlankString(entry.presentation_section, nestedCase?.presentation_section, rawCase?.presentation_section)),
      readiness_state: upperTrim(firstNonBlankString(entry.readiness_state, nestedCase?.readiness_state, rawCase?.readiness_state)),
      raw_case: isPlainObject(rawCase) ? deep(rawCase) : (isPlainObject(nestedCase) ? deep(nestedCase) : deep(entry)),
      candidate: candidateMeta || {
        candidate_id: candidateId,
        display_name: trimStr(firstNonBlankString(
          entry.candidate_display_name,
          entry.display_name,
          nestedCase?.candidate_display_name,
          nestedCase?.display_name,
          rawCase?.candidate_display_name,
          rawCase?.display_name,
          sourceCandidate?.display_name
        )),
        tms_ref: trimStr(firstNonBlankString(
          entry.candidate_tms_ref,
          entry.tms_ref,
          nestedCase?.candidate_tms_ref,
          nestedCase?.tms_ref,
          rawCase?.candidate_tms_ref,
          rawCase?.tms_ref,
          sourceCandidate?.tms_ref
        )),
        current_pay_method: upperTrim(firstNonBlankString(
          entry.current_pay_method,
          entry.pay_channel,
          nestedCase?.current_pay_method,
          nestedCase?.pay_channel,
          rawCase?.current_pay_method,
          rawCase?.pay_channel,
          sourceCandidate?.current_pay_method
        ))
      }
    };

    normalized.__display_identity_key = makeEntryIdentityKey(normalized);
    return normalized.__display_identity_key ? normalized : null;
  };

  const addNormalizedEntry = (entry) => {
    if (!entry || !entry.__display_identity_key) return;
    if (seenEntryKeys.has(entry.__display_identity_key)) return;
    seenEntryKeys.add(entry.__display_identity_key);
    caseEntries.push(entry);

    const caseKey = trimStr(entry.case_key);
    const financeCaseId = trimStr(entry.finance_case_id);
    const candidateId = trimStr(entry.candidate_id);
    const linkedTimesheetId = trimStr(entry.linked_timesheet_id);

    if (caseKey) {
      if (!caseEntryByCaseKey.has(caseKey)) caseEntryByCaseKey.set(caseKey, entry);
      const scopedCaseKey = makeScopedKey('CASE_KEY', candidateId, caseKey);
      if (scopedCaseKey && !caseEntryByScopedCaseKey.has(scopedCaseKey)) caseEntryByScopedCaseKey.set(scopedCaseKey, entry);
    }
    if (financeCaseId) {
      if (!caseEntryByFinanceCaseId.has(financeCaseId)) caseEntryByFinanceCaseId.set(financeCaseId, entry);
      const scopedFinanceCaseKey = makeScopedKey('FINANCE_CASE', candidateId, financeCaseId);
      if (scopedFinanceCaseKey && !caseEntryByScopedFinanceCaseId.has(scopedFinanceCaseKey)) caseEntryByScopedFinanceCaseId.set(scopedFinanceCaseKey, entry);
    }
    if (candidateId && linkedTimesheetId) {
      const candidateTimesheetKey = makeCandidateTimesheetKey(candidateId, linkedTimesheetId);
      if (candidateTimesheetKey && !caseEntryByCandidateTimesheet.has(candidateTimesheetKey)) caseEntryByCandidateTimesheet.set(candidateTimesheetKey, entry);
    }
  };

  const candidateSourceRows = asArray(candidateRows).filter((candidateRow) => isPlainObject(candidateRow));
  for (const candidateRow of candidateSourceRows) {
    const states = asArray(candidateRow?.case_resolution_states).filter((entry) => isPlainObject(entry));
    for (const rawEntry of states) {
      addNormalizedEntry(normalizeCaseEntry(rawEntry, candidateRow));
    }
  }

  for (const rawEntry of asArray(preview.case_resolution_states).filter((entry) => isPlainObject(entry))) {
    addNormalizedEntry(normalizeCaseEntry(rawEntry, null));
  }

  for (const rawEntry of asArray(cacheObj.case_resolution_states).filter((entry) => isPlainObject(entry))) {
    addNormalizedEntry(normalizeCaseEntry(rawEntry, null));
  }

  // Current preview-page case rows are authoritative and can carry the
  // resolution summary/components directly without a decorated case-state entry.
  for (const rawEntry of casePreviewRows.filter((entry) => isPlainObject(entry))) {
    addNormalizedEntry(normalizeCaseEntry(rawEntry, null));
  }

  const findEntryForLine = (line) => {
    const previewLine = isPlainObject(line) ? line : {};
    const lineRawCaseEnvelope = firstPlainObject(previewLine.raw_case, previewLine.case);
    const lineRawCase = unwrapRawCase(lineRawCaseEnvelope);
    const lineResolutionSummary = firstPlainObject(
      previewLine.case_resolution_summary,
      previewLine.caseResolutionSummary,
      previewLine.row_json?.case_resolution_summary,
      previewLine.row_json?.caseResolutionSummary,
      previewLine.rowJson?.case_resolution_summary,
      previewLine.rowJson?.caseResolutionSummary
    );
    const candidateId = trimStr(firstNonBlankString(previewLine.candidate_id, lineRawCase?.candidate_id, lineResolutionSummary?.candidate_id));
    const caseKey = trimStr(firstNonBlankString(previewLine.case_key, lineRawCase?.case_key, lineResolutionSummary?.case_key));
    const financeCaseId = trimStr(firstNonBlankString(previewLine.finance_case_id, lineRawCase?.finance_case_id, lineResolutionSummary?.finance_case_id));
    const linkedTimesheetId = trimStr(firstNonBlankString(
      previewLine.linked_timesheet_id,
      previewLine.timesheet_id,
      lineRawCase?.linked_timesheet_id,
      lineRawCase?.timesheet_id,
      lineResolutionSummary?.linked_timesheet_id,
      lineResolutionSummary?.timesheet_id
    ));

    if (candidateId && caseKey) {
      const scopedCaseKey = makeScopedKey('CASE_KEY', candidateId, caseKey);
      if (caseEntryByScopedCaseKey.has(scopedCaseKey)) return caseEntryByScopedCaseKey.get(scopedCaseKey);
    }
    if (caseKey && caseEntryByCaseKey.has(caseKey)) return caseEntryByCaseKey.get(caseKey);

    if (candidateId && financeCaseId) {
      const scopedFinanceCaseKey = makeScopedKey('FINANCE_CASE', candidateId, financeCaseId);
      if (caseEntryByScopedFinanceCaseId.has(scopedFinanceCaseKey)) return caseEntryByScopedFinanceCaseId.get(scopedFinanceCaseKey);
    }
    if (financeCaseId && caseEntryByFinanceCaseId.has(financeCaseId)) return caseEntryByFinanceCaseId.get(financeCaseId);

    if (candidateId && linkedTimesheetId) {
      const candidateTimesheetKey = makeCandidateTimesheetKey(candidateId, linkedTimesheetId);
      if (caseEntryByCandidateTimesheet.has(candidateTimesheetKey)) return caseEntryByCandidateTimesheet.get(candidateTimesheetKey);
    }

    return null;
  };

  const matchedEntryKeys = new Set();
  const displayEntryByIdentity = new Map();
  const casePreviewLinesEnriched = casePreviewRows.map((line) => {
    const enrichedLine = deep(line);
    const matchedEntry = findEntryForLine(line);
    if (matchedEntry) {
      const displayEntry = buildOverlayedDisplayEntry(matchedEntry, line);
      enrichedLine.__case_entry = deep(displayEntry);
      enrichedLine.case_key = trimStr(enrichedLine.case_key || displayEntry.case_key || '');
      enrichedLine.finance_case_id = trimStr(enrichedLine.finance_case_id || displayEntry.finance_case_id || '');
      enrichedLine.linked_timesheet_id = trimStr(enrichedLine.linked_timesheet_id || displayEntry.linked_timesheet_id || '');
      matchedEntryKeys.add(matchedEntry.__display_identity_key);
      if (!displayEntryByIdentity.has(matchedEntry.__display_identity_key)) {
        displayEntryByIdentity.set(matchedEntry.__display_identity_key, deep(displayEntry));
      }
    } else {
      enrichedLine.__case_entry = null;
      enrichedLine.__case_join_missed = true;
    }
    return enrichedLine;
  });

  const displayCaseEntries = Array.from(displayEntryByIdentity.values());

  return {
    caseEntries: caseEntries.map((entry) => deep(entry)),
    caseGroups: groupEntriesByCandidate(displayCaseEntries),
    casePreviewLinesEnriched,
    caseEntryByCaseKey,
    caseEntryByFinanceCaseId,
    caseEntryByCandidateTimesheet
  };
};

const renderCaseActionButtons = (entry) => {
  const buttons = [];
  const actionableSuggestedResolutionAvailable = entry?.has_actionable_suggested_resolution === true;
  const actionableSuggestedResolutionRequired = entry?.resolution_action_requires_actionable_components === true;
  if (
    entry.case_needs_resolution
    && !entry.case_resolution_satisfied_now
    && (!actionableSuggestedResolutionRequired || actionableSuggestedResolutionAvailable)
  ) {
    const resolutionFamily = upperTrim(entry.resolution_family);
    if (resolutionFamily === 'TAXABLE_CHANNEL_RESTRUCTURE') {
      buttons.push(`
        <button
          type="button"
          class="btn btn-xs btn-outline"
          data-action="banking:pay:openTaxableFinanceCaseRestructure"
          data-candidate-id="${enc(entry.candidate_id)}"
          data-case-key="${enc(trimStr(entry.case_key || ''))}"
          data-finance-case-id="${enc(trimStr(entry.finance_case_id || ''))}"
          data-timesheet-id="${enc(trimStr(entry.linked_timesheet_id || ''))}"
          ${getCandidateActionDisabledAttrs(entry.candidate_id, 'Review the suggested taxable finance restructure for this case')}
        >Suggested Restructure</button>
      `);
    } else if (resolutionFamily === 'NON_BUCKET') {
      buttons.push(`
        <button
          type="button"
          class="btn btn-xs btn-outline"
          data-action="banking:pay:openNonBucketResolution"
          data-candidate-id="${enc(entry.candidate_id)}"
          data-case-key="${enc(trimStr(entry.case_key || ''))}"
          data-finance-case-id="${enc(trimStr(entry.finance_case_id || ''))}"
          data-timesheet-id="${enc(trimStr(entry.linked_timesheet_id || ''))}"
          ${getCandidateActionDisabledAttrs(entry.candidate_id, 'Review the suggested gross total for this case')}
        >${enc(trimStr(entry.resolution_action_label || 'Suggested Gross Total'))}</button>
      `);
    } else {
      buttons.push(`
        <button
          type="button"
          class="btn btn-xs btn-outline"
          data-action="banking:pay:openBucketedResolution"
          data-candidate-id="${enc(entry.candidate_id)}"
          data-case-key="${enc(trimStr(entry.case_key || ''))}"
          data-finance-case-id="${enc(trimStr(entry.finance_case_id || ''))}"
          data-timesheet-id="${enc(trimStr(entry.linked_timesheet_id || ''))}"
          ${getCandidateActionDisabledAttrs(entry.candidate_id, 'Review the suggested rates for this case')}
        >${enc(trimStr(entry.resolution_action_label || 'Suggested Rate'))}</button>
      `);
    }
  }
  if (trimStr(entry.linked_timesheet_id || '')) {
    buttons.push(`
      <button
        type="button"
        class="btn btn-xs btn-outline"
        data-action="banking:pay:toggleExcludeTimesheet"
        data-timesheet-id="${enc(trimStr(entry.linked_timesheet_id || ''))}"
        data-candidate-id="${enc(entry.candidate_id)}"
        ${asBool(entry.excluded_from_run) ? 'data-excluded="true"' : 'data-excluded="false"'}
        ${getCandidateActionDisabledAttrs(entry.candidate_id, asBool(entry.excluded_from_run) ? 'Include this case back into the current run' : 'Exclude this case from the current run')}
      >${enc(asBool(entry.excluded_from_run) ? 'Include case' : 'Exclude case')}</button>
    `);
  }
  return buttons.join('');
};

const renderComponentRows = (entry) => {
  const comps = Array.isArray(entry.components) ? entry.components.filter((c) => isPlainObject(c)) : [];
  if (!comps.length) {
    return `<div class="mini" style="opacity:.8; margin-top:8px;">No bucket detail is available in the current preview payload for this case.</div>`;
  }

  const fmtMaybeNum = (value, decimals = 2) => {
    const n = Number(value);
    if (!Number.isFinite(n)) return '—';
    return n.toFixed(decimals);
  };

  const rows = comps.map((component) => {
    const fixedNoAction = component.is_fixed_reimbursement || component.is_fixed_no_action_taxable_row || upperTrim(component.resolution_state || '') === 'FIXED' || upperTrim(component.resolution_state || '') === 'NOT_REQUIRED';
    const needsAction = component.needs_action === true;
    const rowOpacity = fixedNoAction && !needsAction ? '0.6' : '1';
    const candidateActionAttrs = getCandidateActionDisabledAttrs(entry?.candidate_id, 'Resolve this component');
    const showSuggestedRate = component.show_suggested_rate === true && component.suggested_available === true;
    const showManualRate = component.show_manual_rate_control === true;
    const showManualAmount = component.show_manual_amount_control === true;
    const clearBtn = (component.has_operator_choice || upperTrim(component.resolution_state || '') === 'STALE' || upperTrim(component.resolution_state || '') === 'RESOLVED')
      ? `<button type="button" class="btn btn-xs btn-outline" data-action="banking:pay:componentClearResolution" data-candidate-id="${enc(entry.candidate_id)}" data-case-key="${enc(entry.case_key)}" data-finance-case-id="${enc(entry.finance_case_id || '')}" data-timesheet-id="${enc(entry.linked_timesheet_id || '')}" data-finance-component-id="${enc(trimStr(component.finance_component_id || ''))}" data-component-key="${enc(trimStr(component.key || ''))}" data-source-family-key="${enc(trimStr(component.source_family_key || ''))}" data-component-key-type="${enc(trimStr(component.component_key_type || ''))}" data-component-key-value="${enc(trimStr(component.component_key_value || ''))}" data-classification="${enc(trimStr(component.classification || ''))}" data-bucket-code="${enc(trimStr(component.bucket_code || ''))}" data-source-basis-fingerprint="${enc(trimStr(component.source_basis_fingerprint || ''))}" data-source-basis-json="${enc(JSON.stringify(component.source_basis_json || {}))}" data-source-units="${enc(component.source_units == null ? '' : String(component.source_units))}" data-source-rate="${enc(component.source_rate == null ? '' : String(component.source_rate))}" data-target-rate="${enc(component.target_rate == null ? '' : String(component.target_rate))}" data-source-charge-rate="${enc(component.source_charge_rate == null ? '' : String(component.source_charge_rate))}" ${candidateActionAttrs}>Clear</button>`
      : '';
    const actionButtons = [];
    if (showSuggestedRate) {
      actionButtons.push(`<button type="button" class="btn btn-xs btn-outline" data-action="banking:pay:componentUseSuggested" data-candidate-id="${enc(entry.candidate_id)}" data-case-key="${enc(entry.case_key)}" data-finance-case-id="${enc(entry.finance_case_id || '')}" data-timesheet-id="${enc(entry.linked_timesheet_id || '')}" data-finance-component-id="${enc(trimStr(component.finance_component_id || ''))}" data-component-key="${enc(trimStr(component.key || ''))}" data-source-family-key="${enc(trimStr(component.source_family_key || ''))}" data-component-key-type="${enc(trimStr(component.component_key_type || ''))}" data-component-key-value="${enc(trimStr(component.component_key_value || ''))}" data-classification="${enc(trimStr(component.classification || ''))}" data-bucket-code="${enc(trimStr(component.bucket_code || ''))}" data-source-basis-fingerprint="${enc(trimStr(component.source_basis_fingerprint || ''))}" data-source-basis-json="${enc(JSON.stringify(component.source_basis_json || {}))}" data-source-units="${enc(component.source_units == null ? '' : String(component.source_units))}" data-source-rate="${enc(component.source_rate == null ? '' : String(component.source_rate))}" data-target-rate="${enc(component.target_rate == null ? '' : String(component.target_rate))}" data-source-charge-rate="${enc(component.source_charge_rate == null ? '' : String(component.source_charge_rate))}" data-resolution-family="${enc(trimStr(entry.resolution_family || ''))}" data-resolution-mode="SUGGESTED_EQUIVALENT_BASIS" ${candidateActionAttrs}>Accept suggestion</button>`);
    }
    if (showManualRate) {
      actionButtons.push(`<button type="button" class="btn btn-xs btn-outline" data-action="banking:pay:componentManualRate" data-candidate-id="${enc(entry.candidate_id)}" data-case-key="${enc(entry.case_key)}" data-finance-case-id="${enc(entry.finance_case_id || '')}" data-timesheet-id="${enc(entry.linked_timesheet_id || '')}" data-finance-component-id="${enc(trimStr(component.finance_component_id || ''))}" data-component-key="${enc(trimStr(component.key || ''))}" data-source-family-key="${enc(trimStr(component.source_family_key || ''))}" data-component-key-type="${enc(trimStr(component.component_key_type || ''))}" data-component-key-value="${enc(trimStr(component.component_key_value || ''))}" data-classification="${enc(trimStr(component.classification || ''))}" data-bucket-code="${enc(trimStr(component.bucket_code || ''))}" data-source-basis-fingerprint="${enc(trimStr(component.source_basis_fingerprint || ''))}" data-source-basis-json="${enc(JSON.stringify(component.source_basis_json || {}))}" data-source-units="${enc(component.source_units == null ? '' : String(component.source_units))}" data-source-rate="${enc(component.source_rate == null ? '' : String(component.source_rate))}" data-target-rate="${enc(component.target_rate == null ? '' : String(component.target_rate))}" data-source-charge-rate="${enc(component.source_charge_rate == null ? '' : String(component.source_charge_rate))}" data-resolution-family="${enc(trimStr(entry.resolution_family || ''))}" data-resolution-mode="MANUAL_REPLACEMENT_RATE" ${candidateActionAttrs}>Manual rate</button>`);
    }
    if (showManualAmount) {
      actionButtons.push(`<button type="button" class="btn btn-xs btn-outline" data-action="banking:pay:componentManualAmount" data-candidate-id="${enc(entry.candidate_id)}" data-case-key="${enc(entry.case_key)}" data-finance-case-id="${enc(entry.finance_case_id || '')}" data-timesheet-id="${enc(entry.linked_timesheet_id || '')}" data-finance-component-id="${enc(trimStr(component.finance_component_id || ''))}" data-component-key="${enc(trimStr(component.key || ''))}" data-source-family-key="${enc(trimStr(component.source_family_key || ''))}" data-component-key-type="${enc(trimStr(component.component_key_type || ''))}" data-component-key-value="${enc(trimStr(component.component_key_value || ''))}" data-classification="${enc(trimStr(component.classification || ''))}" data-bucket-code="${enc(trimStr(component.bucket_code || ''))}" data-source-basis-fingerprint="${enc(trimStr(component.source_basis_fingerprint || ''))}" data-source-basis-json="${enc(JSON.stringify(component.source_basis_json || {}))}" data-source-units="${enc(component.source_units == null ? '' : String(component.source_units))}" data-source-rate="${enc(component.source_rate == null ? '' : String(component.source_rate))}" data-target-rate="${enc(component.target_rate == null ? '' : String(component.target_rate))}" data-source-charge-rate="${enc(component.source_charge_rate == null ? '' : String(component.source_charge_rate))}" data-resolution-family="${enc(trimStr(entry.resolution_family || ''))}" data-resolution-mode="MANUAL_AMOUNT" ${candidateActionAttrs}>Manual amount</button>`);
    }
    if (clearBtn) actionButtons.push(clearBtn);

    return `
      <tr style="opacity:${rowOpacity};">
        <td>${enc(trimStr(component.label || component.component_label || component.display_label || component.description || 'Bucket'))}</td>
        <td class="mono" style="text-align:right; white-space:nowrap;">${enc(component.is_rate_bearing ? fmtMaybeNum(component.source_units, 4) : '—')}</td>
        <td class="mono" style="text-align:right; white-space:nowrap;">${enc(component.is_rate_bearing ? fmtMaybeNum(component.source_rate, 2) : '—')}</td>
        <td class="mono" style="text-align:right; white-space:nowrap;">${enc(showSuggestedRate ? fmtMaybeNum(component.target_rate, 2) : '—')}</td>
        <td class="mono" style="text-align:right; white-space:nowrap;">${enc(fmtMoney(component.source_pay_amount))}</td>
        <td class="mono" style="text-align:right; white-space:nowrap;">${enc(fmtMoney(component.target_pay_amount))}</td>
        <td class="mono" style="text-align:right; white-space:nowrap;">${enc(fmtMoney(component.source_charge_amount))}</td>
        <td class="mono" style="text-align:right; white-space:nowrap;">${enc(fmtMoney(component.target_margin_amount))}</td>
        <td><div style="display:flex;flex-direction:column;gap:6px;align-items:flex-start;">${needsAction ? `<span class="pill pill-bad">Needs action</span>` : `<span class="pill">${enc(fixedNoAction ? 'Fixed / no action' : 'No action')}</span>`}${actionButtons.length ? `<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;">${actionButtons.join('')}</div>` : `<div class="mini" style="opacity:.8;">No resolution control required.</div>`}</div></td>
      </tr>
    `;
  }).join('');

  return `
    <div style="margin-top:8px; overflow:auto; border:1px solid var(--line); border-radius:10px;">
      <table class="grid" style="min-width:1280px; table-layout:auto;">
        <thead>
          <tr>
            <th>Bucket</th>
            <th style="width:120px; text-align:right;">Units</th>
            <th style="width:140px; text-align:right;">Current / source rate</th>
            <th style="width:140px; text-align:right;">Suggested / target rate</th>
            <th style="width:140px; text-align:right;">Current / source pay</th>
            <th style="width:140px; text-align:right;">Target pay</th>
            <th style="width:140px; text-align:right;">Current / source charge</th>
            <th style="width:140px; text-align:right;">Target margin</th>
            <th style="width:240px;">Needs action</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
  `;
};

const payeeReadinessBlockerCodes = new Set([
  'BLOCKED_BANK_DETAILS',
  'BLOCKED_NAME_CHECK',
  'BLOCKED_NO_PAYEE_MAP',
  'BLOCKED_UMBRELLA_INACTIVE'
]);

const payeeRouteKeyFrom = (obj, fallback = null) => {
  const entityKind = upperTrim(
    obj?.payee_entity_kind ||
    obj?.payeeEntityKind ||
    obj?.entity_kind ||
    obj?.entityKind ||
    fallback?.payee_entity_kind ||
    fallback?.payeeEntityKind ||
    fallback?.entity_kind ||
    fallback?.entityKind ||
    ''
  );
  const entityId = trimStr(
    obj?.payee_entity_id ||
    obj?.payeeEntityId ||
    obj?.entity_id ||
    obj?.entityId ||
    fallback?.payee_entity_id ||
    fallback?.payeeEntityId ||
    fallback?.entity_id ||
    fallback?.entityId ||
    ''
  );
  const bankDetailsHash = trimStr(
    obj?.bank_details_hash ||
    obj?.bankDetailsHash ||
    obj?.payee_bank_hash ||
    obj?.payeeBankHash ||
    obj?.bank_details_hash_snapshot ||
    obj?.bankDetailsHashSnapshot ||
    obj?.snapshot_bank_details_hash ||
    obj?.snapshotBankDetailsHash ||
    fallback?.bank_details_hash ||
    fallback?.bankDetailsHash ||
    fallback?.payee_bank_hash ||
    fallback?.payeeBankHash ||
    fallback?.bank_details_hash_snapshot ||
    fallback?.bankDetailsHashSnapshot ||
    fallback?.snapshot_bank_details_hash ||
    fallback?.snapshotBankDetailsHash ||
    ''
  );
  if (entityKind && entityId) return `${entityKind}|${entityId}|${bankDetailsHash || 'NO_BANK_HASH'}`;
  const candidateId = trimStr(obj?.candidate_id || obj?.candidateId || fallback?.candidate_id || fallback?.candidateId || '');
  return candidateId ? `CANDIDATE_FALLBACK|${candidateId}` : '';
};

const collectPayeeReadinessBlockedLines = () => {
  const out = [];
  const seen = new Set();

  const existingBlockedRouteKeys = new Set();
  for (const line of asArray(blockedPreviewLines)) {
    const key = payeeRouteKeyFrom(line, candidateMetaById.get(trimStr(line?.candidate_id)) || null);
    if (key) existingBlockedRouteKeys.add(key);
  }

  const amountByCandidateId = new Map();
  for (const line of asArray(canonicalPreviewLines)) {
    if (!isPlainObject(line)) continue;
    const candidateId = trimStr(line?.candidate_id);
    if (!candidateId) continue;
    const amount = toNum(getLineSectionAmount(line), 0);
    if (!amount) continue;
    amountByCandidateId.set(candidateId, Math.round(((amountByCandidateId.get(candidateId) || 0) + amount) * 100) / 100);
  }

  const sourcePayees = [
    ...asArray(pv?.payees),
    ...asArray(wiz.workbench?.payees),
    ...asArray(pv?.non_paye_payees),
    ...asArray(pv?.nonPayePayees),
    ...asArray(pv?.paye_candidates),
    ...asArray(pv?.payeCandidates)
  ].filter((payee) => isPlainObject(payee));

  const candidateIdsWithNonCandidatePayeeRoute = new Set();
  for (const payee of sourcePayees) {
    const candidateId = trimStr(payee?.candidate_id || payee?.candidateId || '');
    if (!candidateId) continue;
    const fallbackMeta = candidateMetaById.get(candidateId) || null;
    const entityKind = upperTrim(
      payee?.payee_entity_kind ||
      payee?.payeeEntityKind ||
      payee?.entity_kind ||
      payee?.entityKind ||
      fallbackMeta?.payee_entity_kind ||
      ''
    );
    const entityId = trimStr(
      payee?.payee_entity_id ||
      payee?.payeeEntityId ||
      payee?.entity_id ||
      payee?.entityId ||
      fallbackMeta?.payee_entity_id ||
      ''
    );
    if (entityKind && entityKind !== 'CANDIDATE' && entityId) {
      candidateIdsWithNonCandidatePayeeRoute.add(candidateId);
    }
  }

  for (const payee of sourcePayees) {
    const candidateId = trimStr(payee?.candidate_id || payee?.candidateId || '');
    const fallbackMeta = candidateMetaById.get(candidateId) || null;
    const sourceEntityKind = upperTrim(
      payee?.payee_entity_kind ||
      payee?.payeeEntityKind ||
      payee?.entity_kind ||
      payee?.entityKind ||
      fallbackMeta?.payee_entity_kind ||
      ''
    );
    if (sourceEntityKind === 'CANDIDATE' && candidateId && candidateIdsWithNonCandidatePayeeRoute.has(candidateId)) {
      continue;
    }
    const blockers = parseBlockerCodes(payee?.blockers);
    const payeeReadinessBlockers = blockers.filter((code) => payeeReadinessBlockerCodes.has(code));
    const readinessStatus = upperTrim(
      payee?.payee_readiness_status ||
      payee?.readiness_status ||
      payee?.payee_setup_status ||
      payee?.payee_readiness_job_status ||
      payee?.readiness_job_status ||
      payee?.latest_payee_readiness_job_status ||
      payee?.latest_job_status ||
      ''
    );
    const latestJobType = upperTrim(payee?.latest_job_type || payee?.job_type || '');
    const hasReadinessJobState = latestJobType === 'PAYEE_READINESS_ENSURE' && (
      payeeReadinessRunningStates.has(readinessStatus) ||
      payeeReadinessFailedStates.has(readinessStatus)
    );
    if (payeeReadinessBlockers.length <= 0 && !hasReadinessJobState) continue;

    const key = payeeRouteKeyFrom(payee, fallbackMeta);
    if (!key || seen.has(key) || existingBlockedRouteKeys.has(key)) continue;
    seen.add(key);

    const entityKind = upperTrim(
      payee?.payee_entity_kind ||
      payee?.payeeEntityKind ||
      payee?.entity_kind ||
      payee?.entityKind ||
      fallbackMeta?.payee_entity_kind ||
      ''
    );
    const entityId = trimStr(
      payee?.payee_entity_id ||
      payee?.payeeEntityId ||
      payee?.entity_id ||
      payee?.entityId ||
      fallbackMeta?.payee_entity_id ||
      ''
    );
    const bankDetailsHash = getExactBankTargetHash(payee, fallbackMeta);
    const nameCheck = isPlainObject(payee?.name_check) ? payee.name_check : {};
    const payeeMap = isPlainObject(payee?.payee_map) ? payee.payee_map : {};
    const amountValues = [
      payee?.section_amount_display,
      payee?.section_amount_ex_vat,
      payee?.amount_display,
      payee?.amount_ex_vat,
      payee?.safe_amount_ex,
      payee?.safe_amount_inc_vat,
      candidateId ? amountByCandidateId.get(candidateId) : undefined
    ];
    let amount = undefined;
    for (const value of amountValues) {
      if (value === undefined || value === null) continue;
      if (typeof value === 'string' && !trimStr(value)) continue;
      amount = value;
      break;
    }

    out.push({
      __payee_readiness_blocker: true,
      __payee_route_key: key,
      line_type: 'PAYEE_READINESS',
      presentation_section: 'BLOCKED_FOR_PAY',
      readiness_state: 'BLOCKED_FOR_PAY',
      candidate_id: candidateId,
      display_name: trimStr(payee?.display_name || payee?.candidate_name || payee?.payee_name || fallbackMeta?.display_name || ''),
      tms_ref: trimStr(payee?.tms_ref || fallbackMeta?.tms_ref || ''),
      client_id: trimStr(payee?.client_id || payee?.clientId || ''),
      client_name: trimStr(payee?.client_name || ''),
      pay_channel: upperTrim(payee?.pay_channel || payee?.current_pay_method || fallbackMeta?.current_pay_method || (entityKind === 'UMBRELLA' ? 'UMBRELLA' : '')),
      current_pay_method: upperTrim(payee?.current_pay_method || payee?.pay_channel || fallbackMeta?.current_pay_method || (entityKind === 'UMBRELLA' ? 'UMBRELLA' : '')),
      payee_entity_kind: entityKind,
      payee_entity_id: entityId,
      bank_details_hash: bankDetailsHash,
      payee_bank_hash: trimStr(payee?.payee_bank_hash || payee?.payeeBankHash || bankDetailsHash || ''),
      bank_details_hash_snapshot: trimStr(payee?.bank_details_hash_snapshot || payee?.bankDetailsHashSnapshot || bankDetailsHash || ''),
      snapshot_bank_details_hash: trimStr(payee?.snapshot_bank_details_hash || payee?.snapshotBankDetailsHash || bankDetailsHash || ''),
      blockers: payeeReadinessBlockers,
      name_check_status: upperTrim(payee?.name_check_status || nameCheck?.status || ''),
      name_check_has_override: Object.prototype.hasOwnProperty.call(payee, 'name_check_has_override')
        ? asBool(payee?.name_check_has_override)
        : asBool(nameCheck?.has_override),
      payee_map_present: Object.prototype.hasOwnProperty.call(payee, 'payee_map_present')
        ? asBool(payee?.payee_map_present)
        : asBool(payeeMap?.present),
      payee_readiness_status: readinessStatus,
      payee_readiness_job_status: upperTrim(payee?.payee_readiness_job_status || payee?.readiness_job_status || ''),
      latest_job_type: latestJobType,
      latest_job_status: upperTrim(payee?.latest_job_status || ''),
      is_ready_for_draft: false,
      section_amount_display: amount == null ? undefined : amount,
      section_amount_ex_vat: amount == null ? undefined : amount,
      amount_display: amount == null ? undefined : amount,
      amount_ex_vat: amount == null ? undefined : amount
    });
  }

  return out;
};
